65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
69	     * at least one dot and no whitespace on either side.
70	     */
71	    private static final Pattern EMAIL_PATTERN =
72	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
73	
74	    /**
75	     * Common street-type abbreviations expanded during address normalization. Keys are the
76	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
77	     * expanded form.
78	     */
79	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
80	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
81	
