83	
84	    private final OwnerMapper ownerMapper;
85	
86	    private final PetMapper petMapper;
87	
88	    private final VisitMapper visitMapper;
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper) {
94	        this.clinicService = clinicService;
95	        this.ownerMapper = ownerMapper;
96	        this.petMapper = petMapper;
97	        this.visitMapper = visitMapper;
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        normalizeAddress(ownerFieldsDto);
129	        validateRequiredFields(ownerFieldsDto);
130	        normalizeTelephone(ownerFieldsDto);
131	        rejectDuplicateTelephone(ownerFieldsDto);
132	        rejectDuplicateHousehold(ownerFieldsDto);
133	        normalizeEmail(ownerFieldsDto);
134	        defaultRegistrationDate(ownerFieldsDto);
135	        HttpHeaders headers = new HttpHeaders();
136	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
137	        assignCustomerCode(owner);
138	        assignNamesakeCount(owner);
139	        assignHousehold(owner, ownerFieldsDto);
140	        this.clinicService.saveOwner(owner);
141	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
142	        headers.setLocation(UriComponentsBuilder.newInstance()
143	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
144	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
150	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
151	        if (currentOwner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        currentOwner.setAddress(ownerFieldsDto.getAddress());
155	        currentOwner.setCity(ownerFieldsDto.getCity());
156	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
157	        currentOwner.setLastName(ownerFieldsDto.getLastName());
158	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
159	        normalizeEmail(ownerFieldsDto);
160	        currentOwner.setEmail(ownerFieldsDto.getEmail());
161	        this.clinicService.saveOwner(currentOwner);
162	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Transactional
167	    @Override
168	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        this.clinicService.deleteOwner(owner);
174	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        HttpHeaders headers = new HttpHeaders();
185	        Pet pet = petMapper.toPet(petFieldsDto);
186	        owner.setId(ownerId);
187	        pet.setOwner(owner);
188	        pet.getType().setName(null);
189	        this.clinicService.savePet(pet);
190	        PetDto petDto = petMapper.toPetDto(pet);
191	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
192	            .buildAndExpand(pet.getId()).toUri());
193	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
199	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
200	        if (currentOwner != null) {
201	            Pet currentPet = this.clinicService.findPetById(petId);
202	            if (currentPet != null) {
203	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
204	                currentPet.setName(petFieldsDto.getName());
205	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
206	                this.clinicService.savePet(currentPet);
207	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
208	            }
209	        }
210	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	    }
