223	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
224	            .buildAndExpand(visit.getId()).toUri());
225	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
226	    }
227	
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
232	        Owner owner = this.clinicService.findOwnerById(ownerId);
233	        if (owner != null) {
234	            Pet pet = owner.getPet(petId);
235	            if (pet != null) {
236	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
237	            }
238	        }
239	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	    }
241	
242	    /**
243	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
244	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
245	     * does not catch). The names of all offending fields are collected so the caller receives a
246	     * 400 response whose {@code errors} array lists each one.
247	     */
248	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
249	        List<String> missingFields = new ArrayList<>();
250	        if (isBlank(ownerFieldsDto.getFirstName())) {
251	            missingFields.add("firstName");
252	        }
253	        if (isBlank(ownerFieldsDto.getLastName())) {
254	            missingFields.add("lastName");
255	        }
256	        if (isBlank(ownerFieldsDto.getAddress())) {
257	            missingFields.add("address");
258	        }
259	        if (isBlank(ownerFieldsDto.getCity())) {
260	            missingFields.add("city");
261	        }
262	        if (isBlank(ownerFieldsDto.getTelephone())) {
263	            missingFields.add("telephone");
264	        }
265	        if (!missingFields.isEmpty()) {
266	            throw new InvalidOwnerFieldsException(missingFields);
267	        }
268	    }
269	
270	    private static boolean isBlank(String value) {
271	        return value == null || value.trim().isEmpty();
272	    }
273	
274	    /**
275	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
276	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
277	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
278	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
279	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
280	     * means an address that is blank after normalization is rejected like a missing one.
281	     */
282	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
283	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
284	    }
285	
286	    /**
287	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
288	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
289	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
290	     * address is returned unchanged, making it safe to apply to stored values during comparison.
291	     */
292	    private static String canonicalAddress(String address) {
293	        if (address == null) {
294	            return null;
295	        }
296	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
297	        if (collapsed.isEmpty()) {
298	            return "";
299	        }
300	        String[] tokens = collapsed.split(" ");
301	        StringBuilder sb = new StringBuilder(collapsed.length());
302	        for (int i = 0; i < tokens.length; i++) {
303	            if (i > 0) {
304	                sb.append(' ');
305	            }
306	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
307	        }
308	        return sb.toString();
309	    }
310	
311	    /**
312	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
313	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
314	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
315	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}. The E.164
316	     * string is written back onto the request so it is what gets stored and returned. Any value that
317	     * cannot form a valid E.164 number is rejected with a 400 response whose {@code errors} array
318	     * names {@code telephone}.
319	     */
320	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
321	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
322	    }
323	
324	    /**
325	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
326	     * (400) naming {@code telephone} when it cannot form a valid number.
327	     */
328	    private static String toE164(String telephone) {
329	        if (telephone == null) {
330	            throw new InvalidOwnerFieldsException(List.of("telephone"));
331	        }
332	        boolean hasCountryCode = telephone.trim().startsWith("+");
333	        String digits = telephone.replaceAll("\\D", "");
334	        String national;
335	        if (hasCountryCode) {
336	            national = digits;
337	        } else {
338	            if (digits.startsWith("0")) {
339	                digits = digits.substring(1);
340	            }
341	            national = "61" + digits;
342	        }
343	        if (!national.matches("[0-9]{8,15}")) {
344	            throw new InvalidOwnerFieldsException(List.of("telephone"));
345	        }
346	        return "+" + national;
347	    }
348	
349	    /**
350	     * Rejects creating an owner whose E.164 telephone is already used by any other owner. The
351	     * incoming value has already been converted to its E.164 form by {@link #normalizeTelephone};
352	     * each existing owner's stored telephone is converted the same way before comparison so numbers
353	     * that only differ in formatting still collide. A match results in a 409 response naming
354	     * {@code telephone}.
355	     */
356	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
357	        String telephone = ownerFieldsDto.getTelephone();
358	        for (Owner existing : this.clinicService.findAllOwners()) {
359	            if (telephone.equals(normalizeExisting(existing.getTelephone()))) {
360	                throw new DuplicateOwnerTelephoneException(telephone);
361	            }
362	        }
363	    }
364	
365	    /**
366	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
367	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
368	     */
369	    private static String normalizeExisting(String telephone) {
370	        try {
371	            return toE164(telephone);
372	        } catch (InvalidOwnerFieldsException ex) {
373	            return null;
374	        }
375	    }
376	
377	    /**
378	     * Rejects creating an owner whose {@code lastName} and {@code address} already belong to another
379	     * owner. Both fields are compared case-insensitively and with runs of whitespace collapsed to a
380	     * single space, so values that differ only in letter case or spacing still collide. When the
381	     * request opts in with {@code sharesHousehold} set to {@code true} the check is skipped, allowing
382	     * household members to share a name and address. A match results in a 409 response naming
383	     * {@code lastName} and {@code address}.
384	     */
385	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
386	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
387	            return;
388	        }
389	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
390	        String address = canonicalAddress(ownerFieldsDto.getAddress());
391	        for (Owner existing : this.clinicService.findAllOwners()) {
392	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
393	                && address.equals(canonicalAddress(existing.getAddress()))) {
394	                throw new DuplicateOwnerHouseholdException(
395	                    ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
396	            }
397	        }
398	    }
399	
400	    /**
401	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
402	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
403	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
404	     */
405	    private static String normalizeForComparison(String value) {
406	        if (value == null) {
407	            return "";
408	        }
409	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
410	    }
411	
412	    /**
413	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
414	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
415	     * written back onto the request so that is what gets stored and returned. A present but invalid
416	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
417	     */
418	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
419	        String email = ownerFieldsDto.getEmail();
420	        if (email == null) {
421	            return;
422	        }
423	        String trimmed = email.trim();
424	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
425	            throw new InvalidOwnerFieldsException(List.of("email"));
426	        }
427	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
428	    }
429	
430	    /**
431	     * Defaults an owner's {@code registrationDate} on create. When the caller supplies no value,
432	     * it is set to the server's current date so every owner is persisted with a registration date;
433	     * a value provided in the request is kept as-is. The date is stored and returned in ISO
434	     * {@code YYYY-MM-DD} format.
435	     */
436	    private void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
437	        if (ownerFieldsDto.getRegistrationDate() == null) {
438	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
439	        }
440	    }
441	
442	    /**
443	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'} where
444	     * {@code LAST3} is the upper-cased first three letters of {@code lastName} and {@code NNNN} is a
445	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
446	     * (e.g. {@code 'SMI-0007'}).
447	     */
448	    private void assignCustomerCode(Owner owner) {
449	        String lastName = owner.getLastName();
450	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
451	        int sequence = this.clinicService.findAllOwners().size() + 1;
452	        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
453	    }
454	
455	    /**
456	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
457	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
458	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
459	     */
460	    private void assignNamesakeCount(Owner owner) {
461	        String firstName = owner.getFirstName();
462	        String lastName = owner.getLastName();
463	        int count = 0;
464	        for (Owner existing : this.clinicService.findAllOwners()) {
465	            if (firstName.equalsIgnoreCase(existing.getFirstName())
466	                && lastName.equalsIgnoreCase(existing.getLastName())) {
467	                count++;
468	            }
469	        }
470	        owner.setNamesakeCount(count);
471	    }
472	
473	    /**
474	     * Assigns the new owner's {@code householdId} when the request opts in with
475	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
476	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
477	     * same way {@link #rejectDuplicateHousehold} matches). The household's members and the new owner
478	     * all end up carrying one stable shared identifier: if any existing member already has a
479	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
480	     * and address. Any existing member that is missing the identifier is updated so the whole
481	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
482	     * identifier is assigned.
483	     */
484	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
485	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
486	            return;
487	        }
488	        String lastName = normalizeForComparison(owner.getLastName());
489	        String address = canonicalAddress(owner.getAddress());
490	        List<Owner> members = new ArrayList<>();
491	        for (Owner existing : this.clinicService.findAllOwners()) {
492	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
493	                && address.equals(canonicalAddress(existing.getAddress()))) {
494	                members.add(existing);
495	            }
496	        }
497	        if (members.isEmpty()) {
498	            return;
499	        }
500	        String householdId = members.stream()
501	            .map(Owner::getHouseholdId)
502	            .filter(id -> id != null && !id.isBlank())
503	            .findFirst()
504	            .orElseGet(() -> newHouseholdId(lastName, address));
505	        owner.setHouseholdId(householdId);
506	        for (Owner member : members) {
507	            if (!householdId.equals(member.getHouseholdId())) {
508	                member.setHouseholdId(householdId);
509	                this.clinicService.saveOwner(member);
510	            }
511	        }
512	    }
513	
514	    /**
515	     * Derives a stable household identifier from the normalized last name and address: the first
516	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
517	     * owners in the same household therefore derive the same value regardless of creation order.
518	     */
519	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
520	        try {
521	            byte[] digest = MessageDigest.getInstance("SHA-256")
522	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
523	            StringBuilder hex = new StringBuilder(digest.length * 2);
524	            for (byte b : digest) {
525	                hex.append(String.format("%02x", b));
526	            }
527	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
528	        } catch (NoSuchAlgorithmException ex) {
529	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
530	        }
531	    }
532	}
